{"query": "
SELECT table_schema, table_name 
FROM information_schema.tables 
WHERE table_schema NOT IN ('pg_catalog', 'information_schema', 'public')
ORDER BY table_schema, table_name;
"}

{"query": "
SELECT column_name, data_type, is_nullable
FROM information_schema.columns
WHERE table_schema = 'employees' AND table_name = 'employee'
ORDER BY ordinal_position;
"}

{"query": "
SELECT column_name, data_type, is_nullable
FROM information_schema.columns
WHERE table_schema = 'employees' AND table_name = 'salary'
ORDER BY ordinal_position;
"}

{"query": "
SELECT COUNT(*) AS total_salary_rows,
       COUNT(DISTINCT employee_id) AS employees_with_salary,
       COUNT(*) FILTER (WHERE to_date = '9999-01-01') AS active_salary_records
FROM employees.salary;
"}
